 19	use vexel_base::Span;
 20	
 21	pub const MAX_SOURCE_BYTES: usize = 16 * 1024 * 1024;
 22	pub const MAX_ATTRIBUTES: usize = 256;
 23	
 24	/// One XML attribute represented by checked name/value ranges in original source.
 25	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 26	pub struct Attribute {
 27	    pub name: Span,
 28	    pub value: Span,
 29	    /// Namespace prefix range, if tokenized as a prefixed name.
 30	    pub prefix: Option<Span>,
 31	}
 32	
 33	/// Bounded view of one element's attributes and source-backed element name.
 34	#[derive(Debug, Clone, Copy)]
 35	pub struct AttributeList<'a> {
 36	    source: &'a [u8],
 37	    element_name: Span,
 38	    attributes: &'a [Attribute],
 39	}
 40	
 41	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 42	pub enum AdapterError {
 43	    SourceLimit,
 44	    TooManyAttributes,
 45	    InvalidSpan,
 46	    InvalidName,
 47	}
 48	
 49	impl<'a> AttributeList<'a> {
 50	    pub fn new(source: &'a [u8], element_name: Span, attributes: &'a [Attribute]) -> Result<Self, AdapterError> {
 51	        if source.len() > MAX_SOURCE_BYTES { return Err(AdapterError::SourceLimit); }
 52	        if attributes.len() > MAX_ATTRIBUTES { return Err(AdapterError::TooManyAttributes); }
 53	        checked_slice(source, element_name).ok_or(AdapterError::InvalidSpan)?;
 54	        for attribute in attributes {
 55	            let name = checked_slice(source, attribute.name).ok_or(AdapterError::InvalidSpan)?;
 56	            checked_slice(source, attribute.value).ok_or(AdapterError::InvalidSpan)?;
 57	            if name.is_empty() || !name.iter().all(|byte| is_name_byte(*byte)) {
 58	                return Err(AdapterError::InvalidName);
 59	            }
 60	            if let Some(prefix) = attribute.prefix {
 61	                checked_slice(source, prefix).ok_or(AdapterError::InvalidSpan)?;
 62	                if prefix.start != attribute.name.start || prefix.end >= attribute.name.end {
 63	                    return Err(AdapterError::InvalidName);
 64	                }
 65	            }
 66	        }
 67	        Ok(Self { source, element_name, attributes })
 68	    }
 69	
 70	    pub fn source(self) -> &'a [u8] { self.source }
 71	    pub fn element_name(self) -> Span { self.element_name }
 72	    pub fn attributes(self) -> &'a [Attribute] { self.attributes }
 73	
 74	    /// Look up an unprefixed attribute by exact, case-sensitive XML name.
 75	    pub fn get(self, name: &[u8]) -> Option<Span> {
 76	        self.attributes.iter().find_map(|attribute| {
 77	            (attribute.prefix.is_none() && checked_slice(self.source, attribute.name) == Some(name))
 78	                .then_some(attribute.value)
 79	        })
 80	    }
 81	
 82	    pub(crate) fn value(self, span: Span) -> Option<&'a [u8]> { checked_slice(self.source, span) }
 83	}
 84	
 85	fn checked_slice(source: &[u8], span: Span) -> Option<&[u8]> {
 86	    (span.start <= span.end).then_some(())?;
 87	    source.get(span.start..span.end)
 88	}
 89	
 90	fn is_name_byte(byte: u8) -> bool {
 91	    byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b':' | b'-' | b'.') || byte >= 0x80
 92	}
