  3	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
  4	pub struct NumberError { pub offset: usize }
  5	
  6	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
  7	pub enum ValueError { InvalidSpan, SourceLimit, OutOfMemory, Number(NumberError), UnsupportedUnit { offset: usize } }
  8	
  9	pub(crate) struct Reader<'a> { bytes: &'a [u8], base: usize, pub index: usize }
 10	
 11	impl<'a> Reader<'a> {
 12	    pub(crate) fn new(bytes: &'a [u8], base: usize) -> Self { Self { bytes, base, index: 0 } }
 13	    pub(crate) fn absolute(&self) -> usize { self.base.saturating_add(self.index) }
 14	    pub(crate) fn skip_space(&mut self) {
 15	        while self.index < self.bytes.len() && is_space(self.bytes[self.index]) { self.index += 1; }
 16	    }
 17	    pub(crate) fn number(&mut self) -> Result<f64, NumberError> {
 18	        self.skip_space();
 19	        let start = self.index;
 20	        let negative = match self.bytes.get(self.index) {
 21	            Some(b'-') => { self.index += 1; true },
 22	            Some(b'+') => { self.index += 1; false },
 23	            _ => false,
 24	        };
 25	        let mut value = 0.0;
 26	        let mut digits = 0usize;
 27	        while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
 28	            value = value * 10.0 + f64::from(byte - b'0');
 29	            self.index += 1;
 30	            digits += 1;
 31	            if !value.is_finite() || value > 1.0e300 { return Err(NumberError { offset: self.absolute() }); }
 32	        }
 33	        if self.bytes.get(self.index) == Some(&b'.') {
 34	            self.index += 1;
 35	            let mut scale = 0.1;
 36	            while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
 37	                value += f64::from(byte - b'0') * scale;
 38	                scale *= 0.1;
 39	                self.index += 1;
 40	                digits += 1;
 41	            }
 42	        }
 43	        if digits == 0 { self.index = start; return Err(NumberError { offset: self.absolute() }); }
 44	        if matches!(self.bytes.get(self.index), Some(b'e' | b'E')) {
 45	            let mut lookahead = self.index + 1;
 46	            if matches!(self.bytes.get(lookahead), Some(b'+' | b'-')) { lookahead += 1; }
 47	            if matches!(self.bytes.get(lookahead), Some(b'0'..=b'9')) {
 48	                self.index += 1;
 49	                let exponent_negative = match self.bytes.get(self.index) {
 50	                    Some(b'-') => { self.index += 1; true },
 51	                    Some(b'+') => { self.index += 1; false },
 52	                    _ => false,
 53	                };
 54	                let mut exponent = 0i32;
 55	                while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
 56	                    if exponent < 10_000 { exponent = exponent.saturating_mul(10).saturating_add(i32::from(byte - b'0')); }
 57	                    self.index += 1;
 58	                }
 59	                if exponent_negative { exponent = -exponent; }
 60	                value *= 10.0_f64.powi(exponent);
 61	            }
 62	        }
 63	        if negative { value = -value; }
 64	        if !value.is_finite() || value.abs() > 1.0e6 {
 65	            return Err(NumberError { offset: self.absolute() });
 66	        }
 67	        Ok(value)
 68	    }
 69	
 70	    pub(crate) fn separator(&mut self) -> bool {
 71	        let before = self.index;
 72	        self.skip_space();
 73	        let had_space = self.index != before;
 74	        if self.bytes.get(self.index) == Some(&b',') {
 75	            self.index += 1;
 76	            self.skip_space();
 77	            return self.index < self.bytes.len() && self.bytes[self.index] != b',';
 78	        }
 79	        had_space && self.index < self.bytes.len()
 80	    }
 81	
 82	    pub(crate) fn finish(&mut self) -> Result<(), NumberError> {
 83	        self.skip_space();
 84	        if self.index == self.bytes.len() { Ok(()) } else { Err(NumberError { offset: self.absolute() }) }
 85	    }
 86	}
 87	
 88	pub(crate) fn is_space(byte: u8) -> bool { matches!(byte, b' ' | b'\t' | b'\r' | b'\n' | 0x0c) }
 89	
 90	pub fn parse_number(source: &[u8], span: Span) -> Result<f64, ValueError> {
 91	    if source.len() > crate::MAX_SOURCE_BYTES { return Err(ValueError::SourceLimit); }
 92	    let bytes = span.slice(source).ok_or(ValueError::InvalidSpan)?;
 93	    let mut reader = Reader::new(bytes, span.start);
 94	    let value = reader.number().map_err(ValueError::Number)?;
 95	    reader.finish().map_err(ValueError::Number)?;
 96	    Ok(value)
 97	}
 98	
 99	pub fn parse_number_list(source: &[u8], span: Span, count: usize) -> Result<Vec<f64>, ValueError> {
100	    if source.len() > crate::MAX_SOURCE_BYTES { return Err(ValueError::SourceLimit); }
101	    let bytes = span.slice(source).ok_or(ValueError::InvalidSpan)?;
102	    if count == 0 || count > 64 { return Err(ValueError::Number(NumberError { offset: span.start })); }
103	    let mut reader = Reader::new(bytes, span.start);
104	    let mut values = Vec::new();
105	    values.try_reserve_exact(count).map_err(|_| ValueError::OutOfMemory)?;
106	    for index in 0..count {
107	        if index != 0 && !reader.separator() { return Err(ValueError::Number(NumberError { offset: reader.absolute() })); }
108	        values.push(reader.number().map_err(ValueError::Number)?);
109	    }
110	    reader.finish().map_err(ValueError::Number)?;
111	    Ok(values)
112	}
