114	pub fn parse_length(source: &[u8], span: Span, percentage_reference: f64) -> Result<f64, ValueError> {
115	    if source.len() > crate::MAX_SOURCE_BYTES { return Err(ValueError::SourceLimit); }
116	    let bytes = span.slice(source).ok_or(ValueError::InvalidSpan)?;
117	    let mut reader = Reader::new(bytes, span.start);
118	    let mut value = reader.number().map_err(ValueError::Number)?;
119	    let suffix = reader.index;
120	    while matches!(reader.bytes.get(reader.index), Some(b'a'..=b'z' | b'A'..=b'Z' | b'%')) { reader.index += 1; }
121	    let unit = &reader.bytes[suffix..reader.index];
122	    let multiplier = match unit {
123	        b"" => 1.0,
124	        b"%" => {
125	            if !percentage_reference.is_finite() || percentage_reference <= 0.0 {
126	                return Err(ValueError::Number(NumberError { offset: span.start + suffix }));
127	            }
128	            percentage_reference / 100.0
129	        }
130	        _ if unit.eq_ignore_ascii_case(b"px") => 1.0,
131	        _ if unit.eq_ignore_ascii_case(b"pt") => 96.0 / 72.0,
132	        _ if unit.eq_ignore_ascii_case(b"mm") => 96.0 / 25.4,
133	        _ if unit.eq_ignore_ascii_case(b"cm") => 96.0 / 2.54,
134	        _ if unit.eq_ignore_ascii_case(b"in") => 96.0,
135	        _ if unit.eq_ignore_ascii_case(b"em") => 16.0,
136	        _ => return Err(ValueError::UnsupportedUnit { offset: span.start + suffix }),
137	    };
138	    value *= multiplier;
139	    reader.finish().map_err(ValueError::Number)?;
140	    if value.is_finite() { Ok(value) } else { Err(ValueError::Number(NumberError { offset: span.end })) }
141	}
