 29	pub fn parse_transform(source: &[u8], span: Span) -> Result<(Affine, usize), TransformError> {
 30	    if source.len() > crate::MAX_SOURCE_BYTES { return Err(TransformError { offset: 0 }); }
 31	    let bytes = span.slice(source).ok_or(TransformError { offset: span.start })?;
 32	    let mut reader = Reader::new(bytes, span.start);
 33	    let mut result = affine_identity();
 34	    let mut operations = 0usize;
 35	    loop {
 36	        reader.skip_space();
 37	        if reader.index == bytes.len() { return Ok((result, operations)); }
 38	        let name_start = reader.index;
 39	        while matches!(bytes.get(reader.index), Some(b'a'..=b'z' | b'A'..=b'Z')) { reader.index += 1; }
 40	        if reader.index == name_start || bytes.get(reader.index) != Some(&b'(') {
 41	            return Err(TransformError { offset: reader.absolute() });
 42	        }
 43	        let name = &bytes[name_start..reader.index];
 44	        reader.index += 1;
 45	        let count = match name {
 46	            b"matrix" => 6,
 47	            b"translate" | b"scale" => 2,
 48	            b"rotate" => 3,
 49	            b"skewX" | b"skewY" => 1,
 50	            _ => return Err(TransformError { offset: span.start + name_start }),
 51	        };
 52	        let mut values = [0.0; 6];
 53	        reader.skip_space();
 54	        if matches!(name, b"translate" | b"scale") {
 55	            values[0] = reader.number().map_err(number_error)?;
 56	            let before = reader.index;
 57	            reader.skip_space();
 58	            if reader.index < bytes.len() && bytes[reader.index] != b')' {
 59	                reader.index = before;
 60	                if !reader.separator() { return Err(TransformError { offset: reader.absolute() }); }
 61	                values[1] = reader.number().map_err(number_error)?;
 62	            } else {
 63	                values[1] = if name == b"scale" { values[0] } else { 0.0 };
 64	            }
 65	        } else if name == b"rotate" {
 66	            values[0] = reader.number().map_err(number_error)?;
 67	            let before = reader.index;
 68	            reader.skip_space();
 69	            if reader.index < bytes.len() && bytes[reader.index] != b')' {
 70	                reader.index = before;
 71	                if !reader.separator() { return Err(TransformError { offset: reader.absolute() }); }
 72	                values[1] = reader.number().map_err(number_error)?;
 73	                if !reader.separator() { return Err(TransformError { offset: reader.absolute() }); }
 74	                values[2] = reader.number().map_err(number_error)?;
 75	            }
 76	        } else {
 77	            for index in 0..count {
 78	                if index != 0 && !reader.separator() { return Err(TransformError { offset: reader.absolute() }); }
 79	                values[index] = reader.number().map_err(number_error)?;
 80	            }
 81	        }
 82	        reader.skip_space();
 83	        if bytes.get(reader.index) != Some(&b')') { return Err(TransformError { offset: reader.absolute() }); }
 84	        reader.index += 1;
 85	
 86	        let operation = match name {
 87	            b"matrix" => Affine { a: values[0], b: values[1], c: values[2], d: values[3], e: values[4], f: values[5] },
 88	            b"translate" => Affine { e: values[0], f: values[1], ..affine_identity() },
 89	            b"scale" => Affine { a: values[0], d: values[1], ..affine_identity() },
 90	            b"skewX" | b"skewY" => {
 91	                let tangent = (values[0] * DEG_TO_RAD).tan();
 92	                if !tangent.is_finite() || tangent.abs() > 1.0e6 { return Err(TransformError { offset: span.start + name_start }); }
 93	                if name == b"skewX" { Affine { c: tangent, ..affine_identity() } }
 94	                else { Affine { b: tangent, ..affine_identity() } }
 95	            }
 96	            b"rotate" => {
 97	                let angle = values[0] * DEG_TO_RAD;
 98	                let (sine, cosine) = angle.sin_cos();
 99	                let mut rotation = Affine { a: cosine, b: sine, c: -sine, d: cosine, e: 0.0, f: 0.0 };
100	                if count == 3 {
101	                    rotation.e = values[1] - cosine * values[1] + sine * values[2];
102	                    rotation.f = values[2] - sine * values[1] - cosine * values[2];
103	                }
104	                rotation
105	            }
106	            _ => return Err(TransformError { offset: span.start + name_start }),
107	        };
108	        operations += 1;
109	        if operations > 64 || !affine_valid(operation) {
110	            return Err(TransformError { offset: span.start + name_start });
111	        }
112	        result = affine_compose(result, operation)
113	            .ok_or(TransformError { offset: span.start + name_start })?;
114	        let after_close = reader.index;
115	        reader.skip_space();
116	        let had_space = reader.index != after_close;
117	        if bytes.get(reader.index) == Some(&b',') {
118	            reader.index += 1;
119	            reader.skip_space();
120	            if reader.index == bytes.len() || bytes[reader.index] == b',' {
121	                return Err(TransformError { offset: reader.absolute() });
122	            }
123	        } else if reader.index < bytes.len() && !had_space {
124	            return Err(TransformError { offset: reader.absolute() });
125	        }
126	    }
127	}
