150	    #[test]
151	    fn inverse_round_trip_limits_and_singularity() {
152	        let matrix = Affine { a: 2.0, b: 0.5, c: -0.25, d: 3.0, e: 8.0, f: -4.0 };
153	        let inverse = affine_inverse(matrix).unwrap();
154	        let point = Point { x: 12.0, y: 7.0 };
155	        let mapped = affine_map_point(matrix, point).unwrap();
156	        let restored = affine_map_point(inverse, mapped).unwrap();
