 91	pub fn viewbox_transform(view_x: f64, view_y: f64, view_width: f64, view_height: f64,
 92	    x: f64, y: f64, width: f64, height: f64, mut aspect: Aspect) -> Result<Affine, MappingError> {
 93	    if ![view_x, view_y, view_width, view_height, x, y, width, height].into_iter().all(f64::is_finite)
 94	        || view_width <= 0.0 || view_height <= 0.0 || width <= 0.0 || height <= 0.0 {
 95	        return Err(err(MappingErrorKind::Viewport, 0));
 96	    }
 97	    if !aspect.set { aspect.align_x = 0.5; aspect.align_y = 0.5; }
 98	    let mut scale_x = width / view_width;
 99	    let mut scale_y = height / view_height;
100	    let mut free_x = 0.0;
101	    let mut free_y = 0.0;
102	    if !aspect.none {
103	        let scale = if aspect.slice { scale_x.max(scale_y) } else { scale_x.min(scale_y) };
104	        scale_x = scale;
105	        scale_y = scale;
106	        free_x = width - view_width * scale;
107	        free_y = height - view_height * scale;
108	    }
109	    let result = Affine { a: scale_x, b: 0.0, c: 0.0, d: scale_y,
110	        e: x + aspect.align_x * free_x - view_x * scale_x,
111	        f: y + aspect.align_y * free_y - view_y * scale_y };
112	    if affine_valid(result) { Ok(result) } else { Err(err(MappingErrorKind::Number, 0)) }
113	}
