    11	pub fn affine_inverse(matrix: Affine) -> Option<Affine> {
    12	    if !affine_valid(matrix) { return None; }
    13	    let determinant = matrix.a * matrix.d - matrix.b * matrix.c;
    14	    if !determinant.is_finite() || determinant.abs() < 1e-15 { return None; }
    15	    let reciprocal = 1.0 / determinant;
    16	    let mut result = Affine {
    17	        a: matrix.d * reciprocal,
    18	        b: -matrix.b * reciprocal,
    19	        c: -matrix.c * reciprocal,
    20	        d: matrix.a * reciprocal,
    21	        e: 0.0,
    22	        f: 0.0,
    23	    };
    24	    result.e = -(result.a * matrix.e + result.c * matrix.f);
    25	    result.f = -(result.b * matrix.e + result.d * matrix.f);
    26	    affine_valid(result).then_some(result)
    27	}
