    47	pub fn parse_preserve_aspect(source: &[u8], span: Span) -> Result<Aspect, MappingError> {
    48	    let bytes = span.slice(source).ok_or(err(MappingErrorKind::InvalidArgument, span.start))?;
    49	    let mut first = 0;
    50	    let mut end = bytes.len();
    51	    while first < end && space(bytes[first]) { first += 1; }
    52	    while end > first && space(bytes[end - 1]) { end -= 1; }
    53	    if first == end { return Err(err(MappingErrorKind::Unsupported, span.start + first)); }
    54	    let mut split = first;
    55	    while split < end && !space(bytes[split]) { split += 1; }
    56	    if &bytes[first..split] == b"defer" {
    57	        first = split;
    58	        while first < end && space(bytes[first]) { first += 1; }
    59	        split = first;
    60	        while split < end && !space(bytes[split]) { split += 1; }
    61	    }
    62	    let token = &bytes[first..split];
    63	    let mut parsed = Aspect { set: true, ..Aspect::default() };
    64	    if token == b"none" {
    65	        skip_space(bytes, &mut split, end);
    66	        if split != end { return Err(err(MappingErrorKind::Unsupported, span.start + split)); }
    67	        parsed.none = true;
    68	        return Ok(parsed);
    69	    }
    70	    const ALIGN: [&[u8]; 9] = [b"xMinYMin", b"xMidYMin", b"xMaxYMin", b"xMinYMid", b"xMidYMid", b"xMaxYMid", b"xMinYMax", b"xMidYMax", b"xMaxYMax"];
    71	    let alignment = ALIGN.iter().position(|candidate| *candidate == token)
    72	        .ok_or(err(MappingErrorKind::Unsupported, span.start + first))?;
    73	    parsed.align_x = (alignment % 3) as f64 * 0.5;
    74	    parsed.align_y = (alignment / 3) as f64 * 0.5;
    75	    first = split;
    76	    skip_space(bytes, &mut first, end);
    77	    if first < end {
    78	        split = first;
    79	        while split < end && !space(bytes[split]) { split += 1; }
    80	        parsed.slice = &bytes[first..split] == b"slice";
    81	        if !parsed.slice && &bytes[first..split] != b"meet" {
    82	            return Err(err(MappingErrorKind::Unsupported, span.start + first));
    83	        }
    84	        first = split;
    85	        skip_space(bytes, &mut first, end);
    86	        if first != end { return Err(err(MappingErrorKind::Unsupported, span.start + first)); }
    87	    }
    88	    Ok(parsed)
    89	}
