   115	pub fn parse_root_viewport(attributes: AttributeList<'_>) -> Result<RootViewport, MappingError> {
   116	    if let Some(namespace) = attributes.get(b"xmlns") {
   117	        if attributes.value(namespace) != Some(SVG_NAMESPACE) {
   118	            return Err(err(MappingErrorKind::Unsupported, namespace.start));
   119	        }
   120	    }
   121	    let width_span = attributes.get(b"width").ok_or(err(MappingErrorKind::Viewport, attributes.element_name().start))?;
   122	    let height_span = attributes.get(b"height").ok_or(err(MappingErrorKind::Viewport, attributes.element_name().start))?;
   123	    let width = parse_length(attributes.source(), width_span, 0.0).map_err(value_error)?;
   124	    let height = parse_length(attributes.source(), height_span, 0.0).map_err(value_error)?;
   125	    if !(1.0..=4096.0).contains(&width) || !(1.0..=4096.0).contains(&height) {
   126	        return Err(err(MappingErrorKind::Viewport, if !(1.0..=4096.0).contains(&width) { width_span.start } else { height_span.start }));
   127	    }
   128	    let mut result = RootViewport { width: width.ceil() as u32, height: height.ceil() as u32,
   129	        view_x: 0.0, view_y: 0.0, view_width: width, view_height: height,
   130	        preserve_aspect: Aspect { set: true, ..Aspect::default() } };
   131	    if let Some(span) = attributes.get(b"viewBox") {
   132	        let view = parse_viewbox(attributes.source(), span)?;
   133	        result.view_x = view[0]; result.view_y = view[1]; result.view_width = view[2]; result.view_height = view[3];
   134	    }
   135	    if let Some(span) = attributes.get(b"preserveAspectRatio") {
   136	        result.preserve_aspect = parse_preserve_aspect(attributes.source(), span)?;
   137	    }
   138	    Ok(result)
   139	}
