   141	pub fn nested_viewport(attributes: AttributeList<'_>, parent_width: f64, parent_height: f64,
   142	    element_transform: Affine) -> Result<NestedViewport, MappingError> {
   143	    let source = attributes.source();
   144	    let x = optional_length(attributes, b"x", parent_width, 0.0)?;
   145	    let y = optional_length(attributes, b"y", parent_height, 0.0)?;
   146	    let width = optional_length(attributes, b"width", parent_width, parent_width)?;
   147	    let height = optional_length(attributes, b"height", parent_height, parent_height)?;
   148	    let element_offset = attributes.element_name().start;
   149	    if width < 0.0 || height < 0.0 || x.abs() > 1.0e6 || y.abs() > 1.0e6 || width > 1.0e6 || height > 1.0e6 {
   150	        return Err(err(MappingErrorKind::Number, element_offset));
   151	    }
   152	    let default = NestedViewport { child_transform: element_transform, viewport_transform: Affine { e: x, f: y, ..identity() },
   153	        clip_points: [Point { x: 0.0, y: 0.0 }; 4], child_width: width, child_height: height, empty: false };
   154	    if width == 0.0 || height == 0.0 { return Ok(NestedViewport { empty: true, ..default }); }
   155	    let local = [Point { x, y }, Point { x: x + width, y }, Point { x: x + width, y: y + height }, Point { x, y: y + height }];
   156	    let mut clip = [Point { x: 0.0, y: 0.0 }; 4];
   157	    for (index, point) in local.into_iter().enumerate() {
   158	        clip[index] = affine_map_point(element_transform, point)
   159	            .ok_or(err(MappingErrorKind::Number, element_offset))?;
   160	    }
   161	    let (viewport, child_width, child_height) = if let Some(span) = attributes.get(b"viewBox") {
   162	        let view = parse_viewbox(source, span)?;
   163	        let aspect = match attributes.get(b"preserveAspectRatio") {
   164	            Some(value) => parse_preserve_aspect(source, value)?,
   165	            None => Aspect::default(),
   166	        };
   167	        (viewbox_transform(view[0], view[1], view[2], view[3], x, y, width, height, aspect)
   168	            .map_err(|error| err(error.kind, span.start))?, view[2], view[3])
   169	    } else { (Affine { e: x, f: y, ..identity() }, width, height) };
   170	    let child = affine_compose(element_transform, viewport)
   171	        .ok_or(err(MappingErrorKind::Number, element_offset))?;
   172	    Ok(NestedViewport { child_transform: child, viewport_transform: viewport, clip_points: clip,
   173	        child_width, child_height, empty: false })
   174	}
   175	
   176	pub fn parse_symbol_mapping(target: AttributeList<'_>, use_element: AttributeList<'_>,
   177	    viewport_width: f64, viewport_height: f64) -> Result<Affine, MappingError> {
   178	    if target.source().as_ptr() != use_element.source().as_ptr() || target.source().len() != use_element.source().len() {
   179	        return Err(err(MappingErrorKind::InvalidArgument, 0));
   180	    }
   181	    let source = target.source();
   182	    let view_span = target.get(b"viewBox").ok_or(err(MappingErrorKind::Viewport, target.element_name().start))?;
   183	    let use_source = use_element.source();
   184	    let view = parse_viewbox(source, view_span)?;
   185	    let width_span = use_element.get(b"width").ok_or(err(MappingErrorKind::Viewport, use_element.element_name().start))?;
   186	    let height_span = use_element.get(b"height").ok_or(err(MappingErrorKind::Viewport, use_element.element_name().start))?;
   187	    let width = parse_length(use_source, width_span, viewport_width).map_err(value_error)?;
   188	    let height = parse_length(use_source, height_span, viewport_height).map_err(value_error)?;
   189	    if width <= 0.0 || height <= 0.0 { return Err(err(MappingErrorKind::Viewport, width_span.start)); }
   190	    let x = optional_length(use_element, b"x", viewport_width, 0.0)?;
   191	    let y = optional_length(use_element, b"y", viewport_height, 0.0)?;
   192	    let aspect_span = use_element.get(b"preserveAspectRatio").or_else(|| target.get(b"preserveAspectRatio"));
   193	    let aspect = match aspect_span {
   194	        Some(span) if span.start != span.end => parse_preserve_aspect(use_source, span)?,
   195	        _ => Aspect::default(),
   196	    };
   197	    viewbox_transform(view[0], view[1], view[2], view[3], x, y, width, height, aspect)
   198	}
   199	
   200	/// Return the first unsupported attribute's name offset, matching symbol fail-closed behavior.
   201	pub fn symbol_attributes_supported(attributes: AttributeList<'_>) -> Result<(), MappingError> {
   202	    const ALLOWED: [&[u8]; 22] = [b"id", b"class", b"style", b"viewBox", b"preserveAspectRatio", b"width", b"height", b"fill", b"fill-rule", b"fill-opacity", b"stroke", b"stroke-width", b"stroke-linecap", b"stroke-linejoin", b"stroke-miterlimit", b"stroke-dasharray", b"stroke-dashoffset", b"stroke-opacity", b"opacity", b"visibility", b"display", b"color"];
   203	    for attribute in attributes.attributes() {
   204	        let name = attribute.name.slice(attributes.source()).unwrap_or_default();
   205	        if attribute.prefix.is_some() || !ALLOWED.contains(&name) {
   206	            return Err(err(MappingErrorKind::Unsupported, attribute.name.start));
   207	        }
   208	    }
   209	    Ok(())
   210	}
   211	
   212	fn parse_viewbox(source: &[u8], span: Span) -> Result<[f64; 4], MappingError> {
   213	    let values = parse_number_list(source, span, 4)
   214	        .map_err(|_| err(MappingErrorKind::Viewport, span.start))?;
   215	    if values[2] <= 0.0 || values[3] <= 0.0 || (values[0] + values[2]).abs() > 1.0e6 || (values[1] + values[3]).abs() > 1.0e6 {
   216	        return Err(err(MappingErrorKind::Viewport, span.start));
   217	    }
   218	    Ok([values[0], values[1], values[2], values[3]])
   219	}
   220	
   221	fn optional_length(attributes: AttributeList<'_>, name: &[u8], reference: f64, default: f64) -> Result<f64, MappingError> {
   222	    match attributes.get(name) { Some(span) => parse_length(attributes.source(), span, reference).map_err(value_error), None => Ok(default) }
   223	}
   224	
   225	fn value_error(error: ValueError) -> MappingError {
   226	    match error {
   227	        ValueError::InvalidSpan | ValueError::SourceLimit | ValueError::OutOfMemory => err(MappingErrorKind::InvalidArgument, 0),
   228	        ValueError::Number(error) => err(MappingErrorKind::Number, error.offset),
   229	        ValueError::UnsupportedUnit { offset } => err(MappingErrorKind::Number, offset),
   230	    }
   231	}
   232	
   233	fn identity() -> Affine { Affine { a: 1.0, b: 0.0, c: 0.0, d: 1.0, e: 0.0, f: 0.0 } }
   234	fn err(kind: MappingErrorKind, offset: usize) -> MappingError { MappingError { kind, offset } }
   235	fn space(byte: u8) -> bool { matches!(byte, b' ' | b'\t' | b'\r' | b'\n' | 0x0c) }
   236	fn skip_space(bytes: &[u8], index: &mut usize, end: usize) { while *index < end && space(bytes[*index]) { *index += 1; } }
