163	bool svg_shape_read_length_value(svg_shape_number_reader *reader,
164	                                 double percentage_reference, double *out)
165	{
166	    if (reader == NULL || out == NULL || !read_number(reader, out)) return false;
167	    size_t suffix = reader->i;
168	    while (reader->i < reader->n &&
169	           ((reader->p[reader->i] >= 'a' && reader->p[reader->i] <= 'z') ||
170	            (reader->p[reader->i] >= 'A' && reader->p[reader->i] <= 'Z') ||
171	            reader->p[reader->i] == '%')) reader->i++;
172	    size_t length = reader->i - suffix;
173	    uint8_t unit[2] = {0U, 0U};
174	    if (length <= sizeof(unit)) {
175	        for (size_t i = 0U; i < length; ++i) {
176	            unit[i] = reader->p[suffix + i];
177	            if (unit[i] >= 'A' && unit[i] <= 'Z')
178	                unit[i] = (uint8_t)(unit[i] + ('a' - 'A'));
179	        }
180	    }
181	    if (length == 0U) return true;
182	    if (length == 1U && reader->p[suffix] == '%') {
183	        if (!isfinite(percentage_reference) || percentage_reference <= 0.0)
184	            return false;
185	        *out *= percentage_reference / 100.0;
186	    } else if (length == 2U && unit[0] == 'p' && unit[1] == 'x') {
187	        /* CSS pixels are the SVG user unit. */
188	    } else if (length == 2U && unit[0] == 'p' && unit[1] == 't') {
189	        *out *= 96.0 / 72.0;
190	    } else if (length == 2U && unit[0] == 'm' && unit[1] == 'm') {
191	        *out *= 96.0 / 25.4;
192	    } else if (length == 2U && unit[0] == 'c' && unit[1] == 'm') {
193	        *out *= 96.0 / 2.54;
194	    } else if (length == 2U && unit[0] == 'i' && unit[1] == 'n') {
195	        *out *= 96.0;
196	    } else if (length == 2U && unit[0] == 'e' && unit[1] == 'm') {
197	        *out *= 16.0;
198	    } else return false;
199	    return isfinite(*out);
200	}
