  6	bool svg_shape_affine_inverse(geom_affine matrix, geom_affine *inverse)
  7	{
  8	    double determinant = matrix.a * matrix.d - matrix.b * matrix.c;
  9	    if (inverse == NULL || !geom_affine_valid(matrix) || !isfinite(determinant) ||
 10	        fabs(determinant) < 1e-15) return false;
 11	    double reciprocal = 1.0 / determinant;
 12	    geom_affine result = {
 13	        matrix.d * reciprocal, -matrix.b * reciprocal,
 14	        -matrix.c * reciprocal, matrix.a * reciprocal, 0.0, 0.0
 15	    };
 16	    result.e = -(result.a * matrix.e + result.c * matrix.f);
 17	    result.f = -(result.b * matrix.e + result.d * matrix.f);
 18	    if (!geom_affine_valid(result)) return false;
 19	    *inverse = result;
 20	    return true;
 21	}
