 40	static bool attr(base_bytes source, svg_xml_token *tokens, size_t count,
 41	                 size_t element, const char *name, svg_xml_span *value)
 42	{
 43	    for (size_t i = element + 1U;
 44	         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
 45	        if (tokens[i].prefix.length == 0U &&
 46	            span_eq(source, tokens[i].local_name, name)) {
