 63	static bool transform_parse(base_bytes source, svg_xml_span span,
 64	                            geom_affine *out, size_t *operation_count)
 65	{
 66	    if (span.offset > source.len || span.length > source.len - span.offset)
 67	        return false;
 68	    number_reader reader = {source.ptr + span.offset, span.length, 0U,
 69	                            span.offset};
 70	    geom_affine result = geom_affine_identity();
 71	    size_t operations = 0U;
 72	    while (true) {
 73	        svg_shape_skip_number_space(&reader);
 74	        if (reader.i == reader.n) break;
 75	        size_t name = reader.i;
 76	        while (reader.i < reader.n &&
 77	               ((source.ptr[span.offset + reader.i] >= 'a' &&
 78	                 source.ptr[span.offset + reader.i] <= 'z') ||
 79	                (source.ptr[span.offset + reader.i] >= 'A' &&
 80	                 source.ptr[span.offset + reader.i] <= 'Z'))) reader.i++;
 81	        if (reader.i == name || reader.i >= reader.n ||
 82	            source.ptr[span.offset + reader.i++] != '(') return false;
 83	        size_t name_length = reader.i - name - 1U;
 84	        double values[6] = {0.0};
 85	        size_t value_count = 0U;
 86	        geom_affine operation = geom_affine_identity();
 87	        if (name_length == 6U &&
 88	            memcmp(source.ptr + span.offset + name, "matrix", 6U) == 0)
 89	            value_count = 6U;
 90	        else if (name_length == 9U &&
 91	                 memcmp(source.ptr + span.offset + name, "translate", 9U) == 0)
 92	            value_count = 2U;
 93	        else if (name_length == 5U &&
 94	                 memcmp(source.ptr + span.offset + name, "scale", 5U) == 0)
 95	            value_count = 2U;
 96	        else if (name_length == 6U &&
 97	                 memcmp(source.ptr + span.offset + name, "rotate", 6U) == 0)
 98	            value_count = 3U;
 99	        else if ((name_length == 5U &&
100	                  memcmp(source.ptr + span.offset + name, "skewX", 5U) == 0) ||
101	                 (name_length == 5U &&
102	                  memcmp(source.ptr + span.offset + name, "skewY", 5U) == 0))
103	            value_count = 1U;
104	        else return false;
105	
106	        svg_shape_skip_number_space(&reader);
107	        if (value_count == 2U && (name_length == 9U || name_length == 5U)) {
108	            if (!svg_shape_read_number_value(&reader, &values[0])) return false;
109	            size_t before = reader.i;
110	            svg_shape_skip_number_space(&reader);
111	            if (reader.i < reader.n &&
112	                source.ptr[span.offset + reader.i] != ')') {
113	                reader.i = before;
114	                if (!svg_shape_next_number_separator(&reader) ||
115	                    !svg_shape_read_number_value(&reader, &values[1])) return false;
116	            } else {
117	                values[1] = name_length == 5U ? values[0] : 0.0;
118	            }
119	        } else if (value_count == 3U) {
120	            if (!svg_shape_read_number_value(&reader, &values[0])) return false;
121	            size_t before = reader.i;
122	            svg_shape_skip_number_space(&reader);
123	            if (reader.i < reader.n &&
124	                source.ptr[span.offset + reader.i] != ')') {
125	                reader.i = before;
126	                if (!svg_shape_next_number_separator(&reader) ||
127	                    !svg_shape_read_number_value(&reader, &values[1]) ||
128	                    !svg_shape_next_number_separator(&reader) ||
129	                    !svg_shape_read_number_value(&reader, &values[2])) return false;
130	            } else {
131	                values[1] = 0.0;
132	                values[2] = 0.0;
133	            }
134	        } else if (!transform_args(&reader, values, value_count)) {
135	            return false;
136	        }
137	        svg_shape_skip_number_space(&reader);
138	        if (reader.i >= reader.n ||
139	            source.ptr[span.offset + reader.i++] != ')') return false;
140	
141	        if (name_length == 6U && value_count == 6U) {
142	            operation = (geom_affine){values[0], values[1], values[2],
143	                                      values[3], values[4], values[5]};
144	        } else if (name_length == 9U) {
145	            operation.e = values[0];
146	            operation.f = values[1];
147	        } else if (name_length == 5U && value_count == 2U) {
148	            operation.a = values[0];
149	            operation.d = values[1];
150	        } else if (name_length == 5U && value_count == 1U) {
151	            double tangent = tan(values[0] * 0.017453292519943295);
152	            if (!isfinite(tangent) || fabs(tangent) > 1000000.0) return false;
153	            if (source.ptr[span.offset + name + 4U] == 'X') operation.c = tangent;
154	            else operation.b = tangent;
155	        } else {
156	            double angle = values[0] * 0.017453292519943295;
157	            double cosine = cos(angle), sine = sin(angle);
158	            operation = (geom_affine){cosine, sine, -sine, cosine, 0.0, 0.0};
159	            if (value_count == 3U) {
160	                operation.e = values[1] - cosine * values[1] +
161	                              sine * values[2];
162	                operation.f = values[2] - sine * values[1] -
163	                              cosine * values[2];
164	            }
165	        }
166	        if (++operations > 64U || !geom_affine_valid(operation) ||
167	            !geom_affine_compose(result, operation, &result)) return false;
168	        size_t after_close = reader.i;
169	        svg_shape_skip_number_space(&reader);
170	        bool had_space = reader.i != after_close;
171	        if (reader.i < reader.n && source.ptr[span.offset + reader.i] == ',') {
172	            reader.i++;
173	            svg_shape_skip_number_space(&reader);
174	            if (reader.i == reader.n) return false;
175	        } else if (reader.i < reader.n && !had_space) {
176	            return false;
177	        }
178	    }
179	    *out = result;
180	    *operation_count = operations;
181	    return true;
182	}
