191	bool svg_shape_transform_node(base_bytes source, svg_xml_token *tokens,
192	                              size_t count, size_t element,
193	                              geom_affine parent, geom_affine *out,
194	                              size_t *operations,
195	                              svg_shape_diagnostic *diagnostic)
196	{
197	    if (tokens == NULL || out == NULL || operations == NULL || element >= count) {
198	        fail(diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT, 0U);
199	        return false;
200	    }
201	    svg_xml_span span;
202	    geom_affine local = geom_affine_identity();
203	    *operations = 0U;
204	    if (attr(source, tokens, count, element, "transform", &span) &&
205	        !transform_parse(source, span, &local, operations)) {
206	        fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, span.offset);
207	        return false;
208	    }
209	    if (!geom_affine_compose(parent, local, out)) {
210	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, tokens[element].name.offset);
211	        return false;
212	    }
213	    return true;
214	}
