 12	static bool token_eq(base_bytes source, size_t first, size_t end,
 13	                     const char *literal)
 14	{
 15	    size_t length = 0U;
 16	    while (literal[length] != '\0') length++;
 17	    return end - first == length && first <= source.len &&
 18	           length <= source.len - first &&
 19	           memcmp(source.ptr + first, literal, length) == 0;
 20	}
