 22	bool svg_shape_parse_preserve_aspect(base_bytes source, svg_xml_span value,
 23	                                     svg_shape_aspect *out)
 24	{
 25	    if (out == NULL || value.offset > source.len ||
 26	        value.length > source.len - value.offset) return false;
 27	    svg_shape_aspect parsed = {.align_x = 0.5, .align_y = 0.5, .set = true};
 28	    size_t first = value.offset, end = value.offset + value.length;
 29	    while (first < end && space(source.ptr[first])) first++;
 30	    while (end > first && space(source.ptr[end - 1U])) end--;
 31	    if (first == end) return false;
 32	    size_t split = first;
 33	    while (split < end && !space(source.ptr[split])) split++;
 34	    if (token_eq(source, first, split, "defer")) {
 35	        first = split;
 36	        while (first < end && space(source.ptr[first])) first++;
 37	        split = first;
 38	        while (split < end && !space(source.ptr[split])) split++;
 39	    }
 40	    if (token_eq(source, first, split, "none")) {
 41	        while (split < end && space(source.ptr[split])) split++;
 42	        if (split != end) return false;
 43	        parsed.none = true;
 44	        *out = parsed;
 45	        return true;
 46	    }
 47	    static const char *const alignments[] = {
 48	        "xMinYMin", "xMidYMin", "xMaxYMin", "xMinYMid", "xMidYMid",
 49	        "xMaxYMid", "xMinYMax", "xMidYMax", "xMaxYMax"
 50	    };
 51	    size_t alignment = 9U;
 52	    for (size_t i = 0U; i < 9U; ++i)
 53	        if (token_eq(source, first, split, alignments[i])) alignment = i;
 54	    if (alignment == 9U) return false;
 55	    parsed.align_x = (double)(alignment % 3U) * 0.5;
 56	    parsed.align_y = (double)(alignment / 3U) * 0.5;
 57	    first = split;
 58	    while (first < end && space(source.ptr[first])) first++;
 59	    if (first < end) {
 60	        split = first;
 61	        while (split < end && !space(source.ptr[split])) split++;
 62	        parsed.slice = token_eq(source, first, split, "slice");
 63	        if (!parsed.slice && !token_eq(source, first, split, "meet"))
 64	            return false;
 65	        first = split;
 66	        while (first < end && space(source.ptr[first])) first++;
 67	        if (first != end) return false;
 68	    }
 69	    *out = parsed;
 70	    return true;
 71	}
