 73	bool svg_shape_viewbox_transform(double view_x, double view_y,
 74	                                 double view_width, double view_height,
 75	                                 double x, double y, double width,
 76	                                 double height, svg_shape_aspect aspect,
 77	                                 geom_affine *out)
 78	{
 79	    if (out == NULL || !isfinite(view_x) || !isfinite(view_y) ||
 80	        !isfinite(view_width) || !isfinite(view_height) ||
 81	        !isfinite(x) || !isfinite(y) || !isfinite(width) ||
 82	        !isfinite(height) || view_width <= 0.0 || view_height <= 0.0 ||
 83	        width <= 0.0 || height <= 0.0) return false;
 84	    if (!aspect.set) {
 85	        aspect.align_x = 0.5;
 86	        aspect.align_y = 0.5;
 87	    }
 88	    double scale_x = width / view_width;
 89	    double scale_y = height / view_height;
 90	    double free_x = 0.0, free_y = 0.0;
 91	    if (!aspect.none) {
 92	        double scale = aspect.slice ? fmax(scale_x, scale_y) :
 93	                                      fmin(scale_x, scale_y);
 94	        scale_x = scale;
 95	        scale_y = scale;
 96	        free_x = width - view_width * scale;
 97	        free_y = height - view_height * scale;
 98	    }
 99	    geom_affine result = {scale_x, 0.0, 0.0, scale_y,
100	        x + aspect.align_x * free_x - view_x * scale_x,
101	        y + aspect.align_y * free_y - view_y * scale_y};
102	    if (!geom_affine_valid(result)) return false;
103	    *out = result;
104	    return true;
105	}
