107	static bool attr(base_bytes source, const svg_xml_token *tokens, size_t count,
108	                 size_t element, const char *name, svg_xml_span *value)
109	{
110	    size_t length = 0U;
111	    while (name[length] != '\0') length++;
112	    for (size_t i = element + 1U;
113	         i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
114	        svg_xml_span candidate = tokens[i].local_name;
115	        if (tokens[i].prefix.length == 0U && candidate.length == length &&
116	            candidate.offset <= source.len &&
117	            length <= source.len - candidate.offset &&
118	            memcmp(source.ptr + candidate.offset, name, length) == 0) {
119	            *value = tokens[i].value;
120	            return true;
121	        }
122	    }
123	    return false;
124	}
