133	bool svg_shape_symbol_attributes_supported(base_bytes source,
134	                                          const svg_xml_token *tokens,
135	                                          size_t token_count, size_t element,
136	                                          size_t *unsupported_offset)
137	{
138	    for (size_t i = element + 1U;
139	         i < token_count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
140	        svg_xml_span name = tokens[i].local_name;
141	        if (tokens[i].prefix.length != 0U) goto unsupported;
142	        bool allowed = svg_shape_span_eq(source, name, "id") ||
143	            svg_shape_span_eq(source, name, "class") ||
144	            svg_shape_span_eq(source, name, "style") ||
145	            svg_shape_span_eq(source, name, "viewBox") ||
146	            svg_shape_span_eq(source, name, "preserveAspectRatio") ||
147	            svg_shape_span_eq(source, name, "width") ||
148	            svg_shape_span_eq(source, name, "height") ||
149	            svg_shape_span_eq(source, name, "fill") ||
150	            svg_shape_span_eq(source, name, "fill-rule") ||
151	            svg_shape_span_eq(source, name, "fill-opacity") ||
152	            svg_shape_span_eq(source, name, "stroke") ||
153	            svg_shape_span_eq(source, name, "stroke-width") ||
154	            svg_shape_span_eq(source, name, "stroke-linecap") ||
155	            svg_shape_span_eq(source, name, "stroke-linejoin") ||
156	            svg_shape_span_eq(source, name, "stroke-miterlimit") ||
157	            svg_shape_span_eq(source, name, "stroke-dasharray") ||
158	            svg_shape_span_eq(source, name, "stroke-dashoffset") ||
159	            svg_shape_span_eq(source, name, "stroke-opacity") ||
160	            svg_shape_span_eq(source, name, "opacity") ||
161	            svg_shape_span_eq(source, name, "visibility") ||
162	            svg_shape_span_eq(source, name, "display") ||
163	            svg_shape_span_eq(source, name, "color");
164	        if (!allowed) goto unsupported;
165	        continue;
166	unsupported:
167	        if (unsupported_offset != NULL)
168	            *unsupported_offset = tokens[i].name.offset;
169	        return false;
170	    }
171	    return true;
172	}
