174	bool svg_shape_symbol_mapping(base_bytes source,
175	                              const svg_xml_token *tokens,
176	                              size_t token_count, size_t target, size_t use,
177	                              double viewport_width, double viewport_height,
178	                              geom_affine *mapping)
179	{
180	    svg_xml_span view_span, width_span, height_span, value;
181	    if (!attr(source, tokens, token_count, target, "viewBox", &view_span) ||
182	        !attr(source, tokens, token_count, use, "width", &width_span) ||
183	        !attr(source, tokens, token_count, use, "height", &height_span))
184	        return false;
185	    double view_box[4], width, height, x = 0.0, y = 0.0;
186	    if (!svg_shape_read_number_list(source, view_span, view_box, 4U) ||
187	        !svg_shape_read_length(source, width_span, viewport_width, &width) ||
188	        !svg_shape_read_length(source, height_span, viewport_height, &height) ||
189	        view_box[2] <= 0.0 || view_box[3] <= 0.0 ||
190	        width <= 0.0 || height <= 0.0) return false;
191	    if (attr(source, tokens, token_count, use, "x", &value) &&
192	        !svg_shape_read_length(source, value, viewport_width, &x)) return false;
193	    if (attr(source, tokens, token_count, use, "y", &value) &&
194	        !svg_shape_read_length(source, value, viewport_height, &y)) return false;
195	    svg_shape_aspect aspect = {.align_x = 0.5, .align_y = 0.5};
196	    if (!attr(source, tokens, token_count, use, "preserveAspectRatio", &value) &&
197	        !attr(source, tokens, token_count, target,
198	              "preserveAspectRatio", &value)) {
199	        *mapping = (geom_affine){fmin(width / view_box[2], height / view_box[3]),
200	            0.0, 0.0, fmin(width / view_box[2], height / view_box[3]),
201	            0.0, 0.0};
202	        double scale = mapping->a;
203	        mapping->e = x + (width - view_box[2] * scale) * 0.5 - view_box[0] * scale;
204	        mapping->f = y + (height - view_box[3] * scale) * 0.5 - view_box[1] * scale;
205	        return geom_affine_valid(*mapping);
206	    }
207	    if (value.length != 0U &&
208	        !svg_shape_parse_preserve_aspect(source, value, &aspect)) return false;
209	    return svg_shape_viewbox_transform(view_box[0], view_box[1],
210	        view_box[2], view_box[3], x, y, width, height, aspect, mapping);
211	}
