213	bool svg_shape_nested_viewport(base_bytes source,
214	                               const svg_xml_token *tokens,
215	                               size_t token_count, size_t element,
216	                               double parent_width, double parent_height,
217	                               geom_affine element_transform,
218	                               geom_affine *child_transform,
219	                               geom_affine *viewport_transform,
220	                               geom_point clip_points[4],
221	                               double *child_width, double *child_height,
222	                               bool *empty,
223	                               svg_shape_diagnostic *diagnostic)
224	{
225	    if (tokens == NULL || child_transform == NULL ||
226	        viewport_transform == NULL || clip_points == NULL ||
227	        child_width == NULL || child_height == NULL || empty == NULL ||
228	        element >= token_count) {
229	        fail(diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT, 0U);
230	        return false;
231	    }
232	    *empty = false;
233	    double x = 0.0, y = 0.0;
234	    double width = parent_width, height = parent_height;
235	    svg_xml_span value;
236	    if (attr(source, tokens, token_count, element, "x", &value) &&
237	        !svg_shape_read_length(source, value, parent_width, &x)) {
238	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
239	        return false;
240	    }
241	    if (attr(source, tokens, token_count, element, "y", &value) &&
242	        !svg_shape_read_length(source, value, parent_height, &y)) {
243	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
244	        return false;
245	    }
246	    if (attr(source, tokens, token_count, element, "width", &value) &&
247	        !svg_shape_read_length(source, value, parent_width, &width)) {
248	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
249	        return false;
250	    }
251	    if (attr(source, tokens, token_count, element, "height", &value) &&
252	        !svg_shape_read_length(source, value, parent_height, &height)) {
253	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
254	        return false;
255	    }
256	    if (width < 0.0 || height < 0.0 || fabs(x) > 1000000.0 ||
257	        fabs(y) > 1000000.0 || width > 1000000.0 || height > 1000000.0) {
258	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, tokens[element].name.offset);
259	        return false;
260	    }
261	    if (width == 0.0 || height == 0.0) {
262	        *empty = true;
263	        return true;
264	    }
265	    geom_point local_clip[4] = {{x, y}, {x + width, y},
266	                                {x + width, y + height}, {x, y + height}};
267	    for (size_t i = 0U; i < 4U; ++i)
268	        if (!geom_affine_map_point(element_transform, local_clip[i],
269	                                   &clip_points[i])) {
270	            fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, tokens[element].name.offset);
271	            return false;
272	        }
273	
274	    geom_affine viewport = {1.0, 0.0, 0.0, 1.0, x, y};
275	    svg_xml_span view_span;
276	    if (attr(source, tokens, token_count, element, "viewBox", &view_span)) {
277	        double view_box[4];
278	        if (!svg_shape_read_number_list(source, view_span, view_box, 4U) ||
279	            view_box[2] <= 0.0 || view_box[3] <= 0.0 ||
280	            fabs(view_box[0] + view_box[2]) > 1000000.0 ||
281	            fabs(view_box[1] + view_box[3]) > 1000000.0) {
282	            fail(diagnostic, SVG_SHAPE_ERROR_VIEWPORT, view_span.offset);
283	            return false;
284	        }
285	        svg_shape_aspect aspect = {.align_x = 0.5, .align_y = 0.5};
286	        if (attr(source, tokens, token_count, element,
287	                 "preserveAspectRatio", &value) &&
288	            !svg_shape_parse_preserve_aspect(source, value, &aspect)) {
289	            fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
290	            return false;
291	        }
292	        if (!svg_shape_viewbox_transform(view_box[0], view_box[1],
293	                view_box[2], view_box[3], x, y, width, height,
294	                aspect, &viewport)) {
295	            fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, view_span.offset);
296	            return false;
297	        }
298	        *child_width = view_box[2];
299	        *child_height = view_box[3];
300	    } else {
301	        *child_width = width;
302	        *child_height = height;
303	    }
304	    if (!geom_affine_compose(element_transform, viewport, child_transform)) {
305	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, tokens[element].name.offset);
306	        return false;
307	    }
308	    *viewport_transform = viewport;
309	    return true;
310	}
