312	bool svg_shape_root_viewport(base_bytes source, svg_xml_token *tokens,
313	                             size_t token_count, size_t element,
314	                             svg_shape_document *document,
315	                             double *viewport_width,
316	                             double *viewport_height,
317	                             svg_shape_diagnostic *diagnostic)
318	{
319	    if (tokens == NULL || document == NULL || viewport_width == NULL ||
320	        viewport_height == NULL || element >= token_count) {
321	        fail(diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT, 0U);
322	        return false;
323	    }
324	    svg_xml_span value = {0}, width_span = {0}, height_span = {0};
325	    if (attr(source, tokens, token_count, element, "xmlns", &value) &&
326	        !token_eq(source, value.offset, value.offset + value.length,
327	                  "http://www.w3.org/2000/svg")) {
328	        fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
329	        return false;
330	    }
331	    if (!attr(source, tokens, token_count, element, "width", &width_span) ||
332	        !attr(source, tokens, token_count, element, "height", &height_span)) {
333	        fail(diagnostic, SVG_SHAPE_ERROR_VIEWPORT, tokens[element].name.offset);
334	        return false;
335	    }
336	    double width, height;
337	    if (!svg_shape_read_dimension(source, width_span, &width)) {
338	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, width_span.offset);
339	        return false;
340	    }
341	    if (!svg_shape_read_dimension(source, height_span, &height)) {
342	        fail(diagnostic, SVG_SHAPE_ERROR_NUMBER, height_span.offset);
343	        return false;
344	    }
345	    if (width < 1.0 || width > 4096.0 || height < 1.0 || height > 4096.0) {
346	        fail(diagnostic, SVG_SHAPE_ERROR_VIEWPORT,
347	             width < 1.0 || width > 4096.0 ? width_span.offset : height_span.offset);
348	        return false;
349	    }
350	    document->width = (uint32_t)ceil(width);
351	    document->height = (uint32_t)ceil(height);
352	    document->view_x = 0.0;
353	    document->view_y = 0.0;
354	    document->view_width = width;
355	    document->view_height = height;
356	    document->preserve_aspect = (svg_shape_aspect){0.5, 0.5, false, false, true};
357	    if (attr(source, tokens, token_count, element, "viewBox", &value)) {
358	        double view_box[4];
359	        if (!svg_shape_read_number_list(source, value, view_box, 4U) ||
360	            view_box[2] <= 0.0 || view_box[3] <= 0.0 ||
361	            fabs(view_box[0] + view_box[2]) > 1000000.0 ||
362	            fabs(view_box[1] + view_box[3]) > 1000000.0) {
363	            fail(diagnostic, SVG_SHAPE_ERROR_VIEWPORT, value.offset);
364	            return false;
365	        }
366	        document->view_x = view_box[0];
367	        document->view_y = view_box[1];
368	        document->view_width = view_box[2];
369	        document->view_height = view_box[3];
370	    }
371	    if (attr(source, tokens, token_count, element,
372	             "preserveAspectRatio", &value) &&
373	        !svg_shape_parse_preserve_aspect(source, value,
374	                                         &document->preserve_aspect)) {
375	        fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
376	        return false;
377	    }
378	    *viewport_width = document->view_width;
379	    *viewport_height = document->view_height;
380	    return true;
381	}
