    12	bool svg_shape_span_eq(base_bytes s, svg_xml_span span, const char *literal)
    13	{
    14	    size_t n = strlen(literal);
    15	    return span.length == n && span.offset <= s.len && n <= s.len - span.offset &&
    16	        memcmp(s.ptr + span.offset, literal, n) == 0;
