    23	double svg_shape_transformed_flatness_tolerance(const svg_shape_builder *b)
    24	{
    25	    double row_norm=fmax(fabs(b->transform.a)+fabs(b->transform.c),
    26	                         fabs(b->transform.b)+fabs(b->transform.d));
    27	    double column_norm=fmax(fabs(b->transform.a)+fabs(b->transform.b),
    28	                            fabs(b->transform.c)+fabs(b->transform.d));
    29	    double scale=sqrt(row_norm*column_norm);
    30	    if (!isfinite(scale) || scale < 1.0) scale=1.0;
    31	    return 0.25/scale;
    32	}
