    37	static void skip_space(number_reader *r)
    38	{
    39	    while (r->i < r->n && (r->p[r->i] == ' ' || r->p[r->i] == '\t' || r->p[r->i] == '\r' || r->p[r->i] == '\n')) r->i++;
    40	}
    41	void svg_shape_skip_path_separators(number_reader *r)
    42	{
    43	    while (r->i < r->n && (r->p[r->i] == ' ' || r->p[r->i] == '\t' || r->p[r->i] == '\r' || r->p[r->i] == '\n' || r->p[r->i] == ',')) r->i++;
    44	}
    45	bool svg_shape_path_operand_boundary(number_reader *r, bool previous_number,
    46	                                 bool previous_arc_flag, char command,
    47	                                 unsigned argument)
    48	{
    49	    size_t before = r->i;
    50	    svg_shape_skip_path_separators(r);
    51	    if (!previous_number || r->i != before) return true;
    52	    if (r->i < r->n && (r->p[r->i] == '+' || r->p[r->i] == '-')) return true;
    53	    if (r->i < r->n && r->p[r->i] == '.') return true;
    54	    return command == 'A' &&
    55	           ((argument == 4U) || (argument == 5U && previous_arc_flag));
    56	}
    57	static bool next_number_separator(number_reader *r)
    58	{
    59	    size_t before = r->i;
    60	    skip_space(r);
    61	    bool had_space = r->i != before;
    62	    if (r->i < r->n && r->p[r->i] == ',') {
    63	        r->i++;
    64	        skip_space(r);
    65	        return r->i < r->n && r->p[r->i] != ',';
    66	    }
    67	    if (had_space) return r->i < r->n;
    68	    return false;
    69	}
    70	/* Decimal conversion is byte-based and independent of the process locale. */
    71	static bool read_number(number_reader *r, double *out)
    72	{
    73	    skip_space(r);
    74	    size_t start = r->i;
    75	    bool negative = false;
    76	    if (r->i < r->n && (r->p[r->i] == '+' || r->p[r->i] == '-')) { negative = r->p[r->i] == '-'; r->i++; }
    77	    double value = 0.0;
    78	    size_t digits = 0;
    79	    while (r->i < r->n && r->p[r->i] >= '0' && r->p[r->i] <= '9') {
    80	        value = value * 10.0 + (double)(r->p[r->i++] - '0'); digits++;
    81	        if (!isfinite(value) || value > 1e300) return false;
    82	    }
    83	    if (r->i < r->n && r->p[r->i] == '.') {
    84	        r->i++; double scale = 0.1;
    85	        while (r->i < r->n && r->p[r->i] >= '0' && r->p[r->i] <= '9') {
    86	            value += (double)(r->p[r->i++] - '0') * scale; scale *= 0.1; digits++;
    87	        }
    88	    }
    89	    if (digits == 0) { r->i = start; return false; }
    90	    int exponent = 0; bool exp_negative = false;
    91	    if (r->i < r->n && (r->p[r->i] == 'e' || r->p[r->i] == 'E')) {
    92	        size_t lookahead = r->i + 1U;
    93	        if (lookahead < r->n && (r->p[lookahead] == '+' || r->p[lookahead] == '-'))
    94	            lookahead++;
    95	        if (lookahead < r->n && r->p[lookahead] >= '0' && r->p[lookahead] <= '9') {
    96	            r->i++;
    97	            if (r->i < r->n && (r->p[r->i] == '+' || r->p[r->i] == '-')) { exp_negative = r->p[r->i] == '-'; r->i++; }
    98	            size_t exp_digits = 0;
    99	            while (r->i < r->n && r->p[r->i] >= '0' && r->p[r->i] <= '9') {
   100	                if (exponent < 10000) exponent = exponent * 10 + (int)(r->p[r->i] - '0');
   101	                r->i++; exp_digits++;
   102	            }
   103	            if (exp_digits == 0) return false;
   104	        }
   105	    }
   106	    if (exp_negative) exponent = -exponent;
   107	    value *= pow(10.0, (double)exponent);
   108	    if (negative) value = -value;
   109	    if (!isfinite(value) || fabs(value) > SHAPE_MAX_COORD) return false;
   110	    *out = value;
